from pathlib import Path
import json,hashlib,os,subprocess
R=Path(__file__).resolve().parents[2];W=Path('F:/OpenRPG_ImportWork');O=W/'physics-transport-reader-v725';B=Path('C:/Users/karen/.rustup/toolchains/1.98.0-x86_64-pc-windows-msvc/bin');assert not O.exists();O.mkdir();(O/'src').mkdir()
def sha(p):
 with Path(p).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
main=r"""
use forge_assets::{source_graph_glb::read_source_graph_glb,source_physics_transport::read_source_physics_transport as read};use forge_core::{bytes_sha256,ContentHash};use serde_json::Value;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let manifest=std::fs::read(dir.join("MANIFEST.v1.json")).unwrap();let doc:Value=serde_json::from_slice(&manifest).unwrap();let mut total=0;let mut candidates=0;let mut negative=0;for row in doc["rows"].as_array().unwrap(){let raw=std::fs::read(row["carrier"].as_str().unwrap()).unwrap();let glb=read_source_graph_glb(&raw).unwrap().unwrap();let hash=bytes_sha256(&raw);let mut resolve=|p:&str|std::fs::read(dir.join(p)).map_err(|e|e.to_string());let components=read(&manifest,bytes_sha256(&manifest),hash,&glb,&mut resolve).unwrap();assert_eq!(components.len(),row["components"].as_array().unwrap().len());total+=components.len();candidates+=components.iter().filter(|c|c.candidate_positions.is_some()).count();assert!(read(&manifest,ContentHash::from_bytes([0;32]),hash,&glb,&mut resolve).is_err());negative+=1;
let mut missing=doc.clone();let selected=missing["rows"].as_array_mut().unwrap().iter_mut().find(|r|r["carrier_sha256"]==row["carrier_sha256"]).unwrap();selected["components"].as_array_mut().unwrap().clear();let encoded=serde_json::to_vec(&missing).unwrap();assert!(read(&encoded,bytes_sha256(&encoded),hash,&glb,&mut resolve).is_err());negative+=1;
let mut duplicate=doc.clone();duplicate["rows"].as_array_mut().unwrap().push(row.clone());let encoded=serde_json::to_vec(&duplicate).unwrap();assert!(read(&encoded,bytes_sha256(&encoded),hash,&glb,&mut resolve).is_err());negative+=1;
if components.iter().any(|c|c.candidate_positions.is_some()){let mut corrupt=|p:&str|{let mut bytes=resolve(p)?;bytes[0]^=1;Ok(bytes)};assert!(read(&manifest,bytes_sha256(&manifest),hash,&glb,&mut corrupt).is_err());negative+=1;let mut escaped=doc.clone();let selected=escaped["rows"].as_array_mut().unwrap().iter_mut().find(|r|r["carrier_sha256"]==row["carrier_sha256"]).unwrap();for c in selected["components"].as_array_mut().unwrap(){if c["shape_transport"]["kind"]=="native_plane_candidate"{c["shape_transport"]["relative_path"]=Value::from("../outside.bin");}}let encoded=serde_json::to_vec(&escaped).unwrap();let mut calls=0;assert!(read(&encoded,bytes_sha256(&encoded),hash,&glb,|_|{calls+=1;Err("must not resolve".into())}).is_err());assert_eq!(calls,0);negative+=1;}
}assert_eq!(total,24);assert_eq!(candidates,17);println!("{}",serde_json::json!({"components":total,"candidate_buffers":candidates,"negative_controls":negative,"carriers":24}));}
"""
(O/'src/main.rs').write_text(main,'utf-8');seed=W/'house-common-collider-host-v718/Cargo.toml';(O/'Cargo.toml').write_text(seed.read_text().replace('house-common-collider-host-v718','physics-transport-reader-v725'));(O/'Cargo.lock').write_bytes((seed.parent/'Cargo.lock').read_bytes());env=os.environ.copy();env.update(RUSTC=str(B/'rustc.exe'),RUSTDOC=str(B/'rustdoc.exe'),CARGO_INCREMENTAL='0',CARGO_TARGET_DIR=str(W/'firepit-static-glb-product-check-v2/target'))
with (O/'lock.log').open('wb') as log:assert subprocess.call([str(B/'cargo.exe'),'generate-lockfile','--offline','--manifest-path',str(O/'Cargo.toml')],env=env,stdout=log,stderr=log)==0
files=[Path(__file__),R/'crates/forge_assets/src/source_physics_transport.rs',R/'crates/forge_assets/src/lib.rs',O/'src/main.rs',O/'Cargo.toml',O/'Cargo.lock',W/'house-physics-transport-v722/MANIFEST.v1.json'];pins={str(p):sha(p) for p in files}
with (O/'cargo.log').open('wb') as log:code=subprocess.call([str(B/'cargo.exe'),'run','--locked','--offline','-j','1','--manifest-path',str(O/'Cargo.toml'),'--',str(W/'house-physics-transport-v722')],env=env,cwd=O,stdout=log,stderr=log)
result={'status':'physics_transport_reader_verified' if code==0 else 'failed','exit_code':code,'unchanged_inputs':all(sha(p)==h for p,h in pins.items()),'input_pins':pins,'full_import_increment':0,'studio_verified':False};(O/'RESULT.v1.json').write_text(json.dumps(result,indent=2),'utf-8');print({k:v for k,v in result.items() if k!='input_pins'})
